require_once __DIR__.'/config/config.php';$code=trim((string)($_GET['code']??''));$s=db()->prepare("SELECT cert.id,cert.certificate_code,cert.issued_at,cred.credential_hash,cred.revoked_at,u.name,c.title,c.language_name FROM certificates cert JOIN certificate_credentials cred ON cred.certificate_id=cert.id JOIN users u ON u.id=cert.user_id JOIN courses c ON c.id=cert.course_id WHERE cert.certificate_code=? LIMIT 1");$s->execute([$code]);$cert=$s->fetch();$valid=false;if($cert&&!$cert['revoked_at']){$q=db()->prepare('SELECT user_id,course_id FROM certificates WHERE id=?');$q->execute([$cert['id']]);$owner=$q->fetch();$valid=$owner&&hash_equals(certificate_signature($cert['certificate_code'],(int)$owner['user_id'],(int)$owner['course_id'],$cert['issued_at']),$cert['credential_hash']);}
$page_title='Certificate verification — LinguaFree';include __DIR__.'/includes/header.php';?>
<div class="verify-wrap"><span class="eyebrow">LINGUAFREE · PUBLIC CREDENTIAL CHECK</span><?php if($valid):?><div class="verify-status">✓ VALID LINGUAFREE CREDENTIAL</div><h1>Certificate verified</h1><p>This certificate ID and its credential fingerprint match LinguaFree's issued record.</p><dl><dt>Learner</dt><dd><?=e($cert['name'])?></dd><dt>Course</dt><dd><?=e($cert['title'])?></dd><dt>Language</dt><dd><?=e($cert['language_name'])?></dd><dt>Issued</dt><dd><?=e(date('F j, Y',strtotime($cert['issued_at'])))?></dd><dt>Certificate ID</dt><dd><?=e($cert['certificate_code'])?></dd><dt>Credential fingerprint</dt><dd class="fingerprint"><?=e($cert['credential_hash'])?></dd></dl><?php else:?><div class="verify-invalid">Certificate not verified</div><p>The code is incorrect, the credential is unavailable, has been revoked, or its signature does not match.</p><?php endif;?></div>
